# NOTE: The acceptance tests live under __tests__/acceptance (no leading space)
TESTS_DIR = PROJECT_ROOT / "__tests__" / "acceptance"

# ----------------------------------------------------------------------
# Test definitions per milestone
# ----------------------------------------------------------------------
