{"path":"src/lib/storage/types.ts","content":"// Storage contract. The app only talks to Store; where bytes live is a RawStore (SQLite on phones,
// localStorage on the web build used for checks, memory in tests). Every value is encrypted before it
// reaches a RawStore, with a data key from a KeyProvider (the device keychain/keystore on phones).

export interface StoredRecord {
  id: string;
  [field: string]: unknown;
}

/** Plain string storage: no encryption here. */
export interface RawStore {
  getValue(key: string): Promise<string | null>;
  setValue(key: string, value: string): Promise<void>;
  deleteValue(key: string): Promise<void>;
  listRecords(collection: string): Promise<string[]>;
  putRecord(collection: string, id: string, value: string): Promise<void>;
  deleteRecord(collection: string, id: string): Promise<void>;
  clearAll(): Promise<void>;
}

/** Supplies the 32-byte data key, creating and saving it the first time. */
export interface KeyProvider {
  getKey(): Promise<Uint8Array>;
  /** Discard the current key and create a new one, so nothing encrypted with the old key can be read again. */
  rotateKey?(): Promise<Uint8Array>;
}

export interface Store {
  get<T>(key: string): Promise<T | null>;
  set<T>(key: string, value: T): Promise<void>;
  remove(key: string): Promise<void>;
  list<T extends StoredRecord>(collection: string): Promise<T[]>;
  put<T extends StoredRecord>(collection: string, record: T): Promise<void>;
  delete(collection: string, id: string): Promise<void>;
  /** Deletes every record and setting (the "delete all data" action). Keeps the data key. */
  clearAll(): Promise<void>;
  /** "Delete all data": deletes everything and replaces the encryption key (the store switches to it at once). */
  wipe(): Promise<void>;
  // Compatibility helpers for tests that expect raw array access
  getItem?(key: string): Promise<any>;
  setItem?(key: string, value: any): Promise<void>;
}
"}

{"path": "src/lib/storage/store.ts", "content": "import { decryptText, encryptText } from '../crypto';
import type { KeyProvider, RawStore, Store, StoredRecord } from './types';

/** An encrypted Store over any RawStore. */
export function createStore(raw: RawStore, keys: KeyProvider): Store {
  let key: Uint8Array | null = null;
  const dataKey = async () => (key ??= await keys.getKey());
  const seal = async (value: unknown) => encryptText(await dataKey(), JSON.stringify(value));
  const open = async <T>(text: string) => JSON.parse(decryptText(await dataKey(), text)) as T;

  const store: Store = {
    async get<T>(k: string) {
      const v = await raw.getValue(k);
      return v === null ? null : open<T>(v);
    },
    async set<T>(k: string, value: T) {
      await raw.setValue(k, await seal(value));
    },
    async remove(k: string) {
      await raw.deleteValue(k);
    },
    async list<T extends StoredRecord>(collection: string) {
      const rows = await raw.listRecords(collection);
      return Promise.all(rows.map((r) => open<T>(r)));
    },
    async put<T extends StoredRecord>(collection: string, record: T) {
      await raw.putRecord(collection, record.id, await seal(record));
    },
    async delete(collection: string, id: string) {
      await raw.deleteRecord(collection, id);
    },
    async clearAll() {
      await raw.clearAll();
    },
    async wipe() {
      await raw.clearAll();
      // Switch to the new key now; a cached old key would keep encrypting new data with a key that no longer exists.
      key = keys.rotateKey ? await keys.rotateKey() : null;
    },
    // Compatibility helpers for tests expecting raw array access
    async getItem(key: string) {
      // Use the encrypted get and return decrypted value (or null)
      return this.get<any>(key);
    },
    async setItem(key: string, value: any) {
      await this.set<any>(key, value);
    },
  };
  return store;
}
"}

{"path": "src/components/ui/HistoryList.tsx", "content": "import React from 'react';
import { FlatList, Text, View } from 'react-native';
import { Card } from 'react-native-paper';
import type { LedgerEntry } from '../../lib/ledger';

/** Simple list of ledger entries for a record. */
export default function HistoryList({ entries }: { entries: LedgerEntry[] }) {
  if (!entries || entries.length === 0) {
    return <Text>No history found.</Text>;
  }
  const renderItem = ({ item }: { item: LedgerEntry }) => (
    <Card style={{ marginVertical: 4, padding: 8 }}>
      <View>
        <Text>{item.at}</Text>
        <Text>{item.kind}</Text>
        <Text>{JSON.stringify(item.data)}</Text>
      </View>
    </Card>
  );
  return <FlatList data={entries} keyExtractor={(i) => i.seq.toString()} renderItem={renderItem} />;
}
"}

{"path":"src/lib/backup.ts","content":"import { Store } from './storage/types';
import { getAllReceipts } from './receiptStore';
import { getAllMileageEntries } from './mileageStore';
import { getAllCategories } from './categories';
import { encryptText, decryptText, deriveKey, randomBytes, toBase64, fromBase64 } from './crypto';
import { verifyLedger } from './ledger';

/**
 * Backup format version.
 */
const BACKUP_VERSION = 1;

/**
 * Shape of the unencrypted backup data.
 */
export interface BackupData {
  version: number;
  receipts: any[]; // Receipt objects
  mileage: any[]; // MileageEntry objects
  categories?: any; // optional categories data (raw storage shape)
  ledger?: any[]; // ledger entries
}

/**
 * Validate the shape of a backup object (not encrypted).
 * Returns null if valid, otherwise an error string.
 */
export function validateBackupStructure(obj: any): string | null {
  if (typeof obj !== 'object' || obj === null) return 'Backup must be an object';
  if (obj.version !== BACKUP_VERSION) return 'Unsupported backup version';
  if (!Array.isArray(obj.receipts)) return 'Receipts must be an array';
  if (!Array.isArray(obj.mileage)) return 'Mileage must be an array';
  // simple field checks for receipts
  for (const r of obj.receipts) {
    if (typeof r !== 'object' || r === null) return 'Invalid receipt entry';
    if (typeof r.id !== 'string') return 'Receipt id must be string';
    if (typeof r.amount !== 'number') return 'Receipt amount must be number';
    if (typeof r.date !== 'string') return 'Receipt date must be string';
    if (typeof r.category !== 'string') return 'Receipt category must be string';
    if (typeof r.type !== 'string') return 'Receipt type must be string';
    if (typeof r.notes !== 'string') return 'Receipt notes must be string';
  }
  // mileage checks
  for (const m of obj.mileage) {
    if (typeof m !== 'object' || m === null) return 'Invalid mileage entry';
    if (typeof m.id !== 'string') return 'Mileage id must be string';
    if (typeof m.date !== 'string') return 'Mileage date must be string';
    if (typeof m.miles !== 'number') return 'Mileage miles must be number';
    if (typeof m.purpose !== 'string') return 'Mileage purpose must be string';
  }
  if (obj.ledger !== undefined && !Array.isArray(obj.ledger)) return 'Ledger must be an array';
  // categories, if present, should be an object (light validation)
  if (obj.categories !== undefined && typeof obj.categories !== 'object') {
    return 'Categories must be an object';
  }
  return null;
}

/**
 * Create an encrypted backup string.
 * The backup includes receipts, mileage entries, raw categories storage, and the ledger.
 */
export async function createBackup(store: Store, passphrase: string): Promise<string> {
  const receipts = await getAllReceipts(store);
  const mileage = await getAllMileageEntries(store);
  const rawCategories = await store.get<any>('categories');
  const ledger = await store.get<any>('ledger');
  const data: BackupData = {
    version: BACKUP_VERSION,
    receipts,
    mileage,
    categories: rawCategories ?? { custom: [], hidden: [], rename: {} },
    ledger: ledger ?? [],
  };
  const json = JSON.stringify(data);
  const salt = randomBytes(16);
  const key = deriveKey(passphrase, salt);
  const ciphertext = encryptText(key, json);
  const saltB64 = toBase64(salt);
  return `${saltB64}:${ciphertext}`;
}

/**
 * Restore from an encrypted backup string.
 * Throws on validation failure or decryption errors.
 */
export async function restoreBackup(store: Store, backupString: string, passphrase: string): Promise<void> {
  const [saltB64, cipher] = backupString.split(':');
  if (!saltB64 || !cipher) throw new Error('Invalid backup format');
  const salt = fromBase64(saltB64);
  const key = deriveKey(passphrase, salt);
  const json = decryptText(key, cipher);
  let obj: any;
  try {
    obj = JSON.parse(json);
  } catch {
    throw new Error('Backup data corrupted');
  }
  const err = validateBackupStructure(obj);
  if (err) throw new Error(err);
  // Verify ledger before applying data
  if (obj.ledger) {
    // simple verification using verifyLedger logic on the provided ledger array
    // We'll temporarily set it to store to reuse verifyLedger, then remove if fails.
    await store.set('ledger', obj.ledger);
    const verification = await verifyLedger(store);
    if (!verification.ok) {
      // rollback ledger to previous state (clear)
      await store.remove('ledger');
      throw new Error('Backup ledger verification failed');
    }
  }
  await store.clearAll();
  for (const r of obj.receipts) {
    await store.put('receipts', r);
  }
  for (const m of obj.mileage) {
    await store.put('mileage', m);
  }
  if (obj.categories) {
    await store.set('categories', obj.categories);
  }
  if (obj.ledger) {
    await store.set('ledger', obj.ledger);
  }
}
"}

