{"path": "src/lib/receiptStore.ts", "content": "// Thin wrapper around Store for the "receipts" collection.
import type { Store, StoredRecord } from './storage/types';
import type { Receipt } from './models';
import { addLedgerEntry } from './ledger';

export async function getAllReceipts(store: Store): Promise<Receipt[]> {
  return store.list<Receipt>('receipts');
}

export async function addReceipt(store: Store, receipt: Receipt): Promise<void> {
  // Cast to StoredRecord to satisfy type constraints.
  await store.put('receipts', receipt as unknown as StoredRecord);
  // Record ledger entry for creation
  await addLedgerEntry(store, 'receipt.created', receipt.id, receipt);
}
"}

{"path": "src/lib/mileageStore.ts", "content": "// Thin wrapper around Store for the "mileage" collection.
import type { Store, StoredRecord } from './storage/types';
import type { MileageEntry } from './models';
import { addLedgerEntry } from './ledger';

export async function getAllMileageEntries(store: Store): Promise<MileageEntry[]> {
  return store.list<MileageEntry>('mileage');
}

export async function addMileageEntry(store: Store, entry: MileageEntry): Promise<void> {
  await store.put('mileage', entry as unknown as StoredRecord);
  await addLedgerEntry(store, 'mileage.created', entry.id, entry);
}
"}

