/** Verify the full ledger chain. Returns an object describing the result. */
export async function verifyLedger(store: Store): Promise<{
  ok: boolean;
  entries: LedgerEntry[];
  firstBadSeq?: number;
  reason?: string;
}> {
  const ledger = await loadLedger(store);
