{"path":"src/lib/ledger.ts","content":"// Ledger core implementation for tamper‑evident record keeping using per‑entry storage (append‑only).

import type { Store, StoredRecord } from './storage/types';
import { sha256 } from '@noble/hashes/sha2.js';
import { bytesToHex, utf8ToBytes } from '@noble/hashes/utils.js';

export type LedgerKind =
  | 'receipt.created'
  | 'receipt.corrected'
  | 'receipt.deleted'
  | 'mileage.created'
  | 'mileage.corrected'
  | 'mileage.deleted'
  | 'imported'
  | 'export.created';

export interface LedgerEntry {
  seq: number; // 1‑based index
  at: string; // ISO timestamp when entry was created
  kind: LedgerKind;
  recordId: string; // id of the receipt/mileage/…
  data: any; // full content after the change (or last content for deletions)
  prevHash: string; // hex 64‑char SHA‑256 of previous entry (or zeros)
  hash: string; // hex 64‑char SHA‑256 of this entry (excluding the hash field)
}

export const LEDGER_ENTRY_PREFIX = 'ledger:'; // key format: ledger:{seq}
export const LEDGER_INDEX_KEY = 'ledger_index'; // stores array of seq numbers
export const LEDGER_INIT_FLAG = 'ledgerInitialized';
export const ZERO_64 = '0'.repeat(64);
export const MAX_LEDGER_ENTRIES = 5000;

/** Produce deterministic JSON with sorted keys (excluding hash). */
function canonical(entry: Omit<LedgerEntry, 'hash'>): string {
  const ordered: any = {};
  const keys = Object.keys(entry).sort();
  for (const k of keys) {
    ordered[k] = (entry as any)[k];
  }
  return JSON.stringify(ordered);
}

function computeHash(entryWithoutHash: Omit<LedgerEntry, 'hash'>): string {
  const json = canonical(entryWithoutHash);
  const hashBytes = sha256(utf8ToBytes(json));
  return bytesToHex(hashBytes);
}

/** Load the ledger index (array of seq numbers). */
async function loadIndex(store: Store): Promise<number[]> {
  const idx = await store.getItem(LEDGER_INDEX_KEY);
  return idx ?? [];
}

/** Append a seq number to the index (immutable previous entries). */
async function pushIndex(store: Store, seq: number): Promise<void> {
  const idx = await loadIndex(store);
  idx.push(seq);
  await store.setItem(LEDGER_INDEX_KEY, idx);
}

/** Load a single entry by seq. */
async function loadEntry(store: Store, seq: number): Promise<LedgerEntry | null> {
  const key = `${LEDGER_ENTRY_PREFIX}${seq}`;
  return await store.getItem<LedgerEntry>(key);
}

/** Load all entries in order. */
export async function getAllLedgerEntries(store: Store): Promise<LedgerEntry[]> {
  const idx = await loadIndex(store);
  const entries: LedgerEntry[] = [];
  for (const seq of idx) {
    const e = await loadEntry(store, seq);
    if (e) entries.push(e);
  }
  return entries;
}

/** Verify the ledger chain using per‑entry storage. */
export async function verifyLedger(store: Store): Promise<{
  ok: boolean;
  entries: LedgerEntry[];
  firstBadSeq?: number;
  reason?: string;
}> {
  const idx = await loadIndex(store);
  const entries: LedgerEntry[] = [];
  for (let i = 0; i < idx.length; i++) {
    const seq = idx[i];
    const entry = await loadEntry(store, seq);
    if (!entry) {
      return { ok: false, entries, firstBadSeq: seq, reason: 'missing entry' };
    }
    const { hash, ...withoutHash } = entry;
    const expectedHash = computeHash(withoutHash as Omit<LedgerEntry, 'hash'>);
    if (hash !== expectedHash) {
      return { ok: false, entries, firstBadSeq: entry.seq, reason: 'hash mismatch' };
    }
    const expectedPrev = i === 0 ? ZERO_64 : entries[i - 1].hash;
    if (entry.prevHash !== expectedPrev) {
      return { ok: false, entries, firstBadSeq: entry.seq, reason: 'prevHash mismatch' };
    }
    entries.push(entry);
  }
  return { ok: true, entries };
}

/** Append a new entry after checking integrity and size limits. */
export async function addLedgerEntry(
  store: Store,
  kind: LedgerKind,
  recordId: string,
  data: any,
): Promise<void> {
  const idx = await loadIndex(store);
  if (idx.length >= MAX_LEDGER_ENTRIES) {
    throw new Error('Ledger size limit exceeded');
  }
  // Verify existing chain before appending
  const verification = await verifyLedger(store);
  if (!verification.ok) {
    throw new Error('Ledger integrity compromised; cannot append');
  }
  const seq = idx.length + 1;
  const at = new Date().toISOString();
  const prevHash = idx.length === 0 ? ZERO_64 : verification.entries[verification.entries.length - 1].hash;
  const entryWithoutHash: Omit<LedgerEntry, 'hash'> = {
    seq,
    at,
    kind,
    recordId,
    data,
    prevHash,
  };
  const hash = computeHash(entryWithoutHash);
  const entry: LedgerEntry = { ...entryWithoutHash, hash };
  // Store entry under its own key
  await store.setItem(`${LEDGER_ENTRY_PREFIX}${seq}`, entry);
  // Update index (append‑only)
  await pushIndex(store, seq);
}

/** Initialise ledger on first launch: import existing receipts/mileage as "imported" entries. */
export async function initLedgerIfNeeded(store: Store): Promise<void> {
  const initFlag = await store.get<boolean>(LEDGER_INIT_FLAG);
  if (initFlag) return;

  const receipts = await store.list<StoredRecord>('receipts');
  for (const r of receipts) {
    await addLedgerEntry(store, 'imported', r.id, r);
  }
  const mileage = await store.list<StoredRecord>('mileage');
  for (const m of mileage) {
    await addLedgerEntry(store, 'imported', m.id, m);
  }
  await store.set<boolean>(LEDGER_INIT_FLAG, true);
}
"}

{"path":"src/lib/receiptStore.ts","content":"// Thin wrapper around Store for the "receipts" collection.
import type { Store, StoredRecord } from './storage/types';
import type { Receipt } from './models';
import { addLedgerEntry, LEDGER_INIT_FLAG } from './ledger';

export async function getAllReceipts(store: Store): Promise<Receipt[]> {
  return store.list<Receipt>('receipts');
}

export async function addReceipt(store: Store, receipt: Receipt): Promise<void> {
  await store.put('receipts', receipt as unknown as StoredRecord);
  // Record ledger entry for creation only after ledger is initialized
  const init = await store.get<boolean>(LEDGER_INIT_FLAG);
  if (init) {
    try {
      await addLedgerEntry(store, 'receipt.created', receipt.id, receipt);
    } catch (e) {
      // If ledger size exceeded, surface a friendly error (could be caught by UI)
      console.error('Failed to add ledger entry for receipt creation:', e);
      throw e;
    }
  }
}

/** Edit an existing receipt; logs a corrected ledger entry. */
export async function editReceipt(store: Store, receipt: Receipt): Promise<void> {
  await store.put('receipts', receipt as unknown as StoredRecord);
  const init = await store.get<boolean>(LEDGER_INIT_FLAG);
  if (init) {
    try {
      await addLedgerEntry(store, 'receipt.corrected', receipt.id, receipt);
    } catch (e) {
      console.error('Failed to add ledger entry for receipt correction:', e);
      throw e;
    }
  }
}

/** Delete a receipt; logs a deleted ledger entry containing last known content. */
export async function deleteReceipt(store: Store, receiptId: string): Promise<void> {
  // Retrieve last known content before deletion for ledger record
  const existing = await store.get<Receipt>(receiptId);
  await store.delete('receipts', receiptId);
  const init = await store.get<boolean>(LEDGER_INIT_FLAG);
  if (init && existing) {
    try {
      await addLedgerEntry(store, 'receipt.deleted', receiptId, existing);
    } catch (e) {
      console.error('Failed to add ledger entry for receipt deletion:', e);
      throw e;
    }
  }
}
"}

{"path": "src/lib/backup.ts", "content": "import { Store } from './storage/types';
import { getAllReceipts } from './receiptStore';
import { getAllMileageEntries } from './mileageStore';
import { getAllCategories } from './categories';
import { encryptText, decryptText, deriveKey, randomBytes, toBase64, fromBase64 } from './crypto';
import { verifyLedger, getAllLedgerEntries, LedgerEntry } from './ledger';

/**
 * Backup format version.
 */
const BACKUP_VERSION = 1;
const MAX_BACKUP_BYTES = 10 * 1024 * 1024; // 10 MiB safety limit

/**
 * Shape of the unencrypted backup data.
 */
export interface BackupData {
  version: number;
  receipts: any[]; // Receipt objects
  mileage: any[]; // MileageEntry objects
  categories?: any; // optional categories data (raw storage shape)
  ledger?: LedgerEntry[]; // ledger entries
}

/**
 * Validate the shape of a backup object (not encrypted).
 * Returns null if valid, otherwise an error string.
 */
export function validateBackupStructure(obj: any): string | null {
  if (typeof obj !== 'object' || obj === null) return 'Backup must be an object';
  if (obj.version !== BACKUP_VERSION) return 'Unsupported backup version';
  if (!Array.isArray(obj.receipts)) return 'Receipts must be an array';
  if (!Array.isArray(obj.mileage)) return 'Mileage must be an array';

  // Validate receipts fields and sanitize photoUri
  for (const r of obj.receipts) {
    if (typeof r !== 'object' || r === null) return 'Invalid receipt entry';
    const allowed = ['id','amount','date','category','type','notes','photoUri'];
    for (const k of Object.keys(r)) {
      if (!allowed.includes(k)) return `Unexpected field ${k} in receipt`;
    }
    if (typeof r.id !== 'string') return 'Receipt id must be string';
    if (typeof r.amount !== 'number') return 'Receipt amount must be number';
    if (typeof r.date !== 'string') return 'Receipt date must be string';
    if (typeof r.category !== 'string') return 'Receipt category must be string';
    if (typeof r.type !== 'string') return 'Receipt type must be string';
    if (typeof r.notes !== 'string') return 'Receipt notes must be string';
    if (r.photoUri !== undefined) {
      if (typeof r.photoUri !== 'string') return 'photoUri must be string';
      if (r.photoUri.includes('..') || r.photoUri.startsWith('/') ) return 'Invalid photoUri path';
    }
  }
  // mileage checks
  for (const m of obj.mileage) {
    if (typeof m !== 'object' || m === null) return 'Invalid mileage entry';
    const allowed = ['id','date','miles','purpose'];
    for (const k of Object.keys(m)) {
      if (!allowed.includes(k)) return `Unexpected field ${k} in mileage`;
    }
    if (typeof m.id !== 'string') return 'Mileage id must be string';
    if (typeof m.date !== 'string') return 'Mileage date must be string';
    if (typeof m.miles !== 'number') return 'Mileage miles must be number';
    if (typeof m.purpose !== 'string') return 'Mileage purpose must be string';
  }
  if (obj.ledger !== undefined && !Array.isArray(obj.ledger)) return 'Ledger must be an array';
  if (obj.categories !== undefined && typeof obj.categories !== 'object') {
    return 'Categories must be an object';
  }
  return null;
}

/** Verify a ledger array (used during restore). */
function verifyLedgerArray(arr: LedgerEntry[]): {
  ok: boolean;
  firstBadSeq?: number;
  reason?: string;
} {
  if (arr.length > MAX_LEDGER_ENTRIES) return { ok: false, reason: 'ledger exceeds max entries' };
  for (let i = 0; i < arr.length; i++) {
    const entry = arr[i];
    const { hash, ...withoutHash } = entry;
    const expectedHash = (function compute(entryNoHash: Omit<LedgerEntry, 'hash'>) {
      const keys = Object.keys(entryNoHash).sort();
      const ordered: any = {};
      for (const k of keys) ordered[k] = (entryNoHash as any)[k];
      const json = JSON.stringify(ordered);
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const { sha256 } = require('@noble/hashes/sha2.js');
      const { bytesToHex, utf8ToBytes } = require('@noble/hashes/utils.js');
      return bytesToHex(sha256(utf8ToBytes(json)));
    })(withoutHash as Omit<LedgerEntry, 'hash'>);
    if (hash !== expectedHash) {
      return { ok: false, firstBadSeq: entry.seq, reason: 'hash mismatch' };
    }
    const expectedPrev = i === 0 ? '0'.repeat(64) : arr[i - 1].hash;
    if (entry.prevHash !== expectedPrev) {
      return { ok: false, firstBadSeq: entry.seq, reason: 'prevHash mismatch' };
    }
  }
  return { ok: true };
}

/**
 * Create an encrypted backup string.
 * The backup includes receipts, mileage entries, raw categories storage, and the ledger.
 */
export async function createBackup(store: Store, passphrase: string): Promise<string> {
  const receipts = await getAllReceipts(store);
  const mileage = await getAllMileageEntries(store);
  const rawCategories = await store.get<any>('categories');
  const ledgerEntries = await getAllLedgerEntries(store);
  const data: BackupData = {
    version: BACKUP_VERSION,
    receipts,
    mileage,
    categories: rawCategories ?? { custom: [], hidden: [], rename: {} },
    ledger: ledgerEntries,
  };
  const json = JSON.stringify(data);
  if (json.length > MAX_BACKUP_BYTES) {
    throw new Error('Backup size exceeds maximum allowed size');
  }
  const salt = randomBytes(16);
  const key = deriveKey(passphrase, salt);
  const ciphertext = encryptText(key, json);
  const saltB64 = toBase64(salt);
  return `${saltB64}:${ciphertext}`;
}

/**
 * Restore from an encrypted backup string.
 * Throws on validation failure or decryption errors.
 */
export async function restoreBackup(store: Store, backupString: string, passphrase: string): Promise<void> {
  const [saltB64, cipher] = backupString.split(':');
  if (!saltB64 || !cipher) throw new Error('Invalid backup format');
  const salt = fromBase64(saltB64);
  const key = deriveKey(passphrase, salt);
  const json = decryptText(key, cipher);
  if (json.length > MAX_BACKUP_BYTES) {
    throw new Error('Backup size exceeds maximum allowed size');
  }
  let obj: any;
  try {
    obj = JSON.parse(json);
  } catch {
    throw new Error('Backup data corrupted');
  }
  const err = validateBackupStructure(obj);
  if (err) throw new Error(err);

  // Clear existing data first
  await store.clearAll();

  // Restore receipts, mileage, categories
  for (const r of obj.receipts) {
    await store.put('receipts', r);
  }
  for (const m of obj.mileage) {
    await store.put('mileage', m);
  }
  if (obj.categories) {
    await store.set('categories', obj.categories);
  }

  // Restore ledger if present and verify it
  if (obj.ledger) {
    const ledgerArr: LedgerEntry[] = obj.ledger;
    const verification = verifyLedgerArray(ledgerArr);
    if (!verification.ok) {
      throw new Error('Backup ledger verification failed');
    }
    // Write entries individually (append‑only)
    for (const entry of ledgerArr) {
      const key = `ledger:${entry.seq}`;
      await store.setItem(key, entry);
    }
    // Recreate index
    const seqs = ledgerArr.map((e) => e.seq);
    await store.setItem('ledger_index', seqs);
  }
}
"}

